const AL = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
function enc(buf){
  let n = 0n;
  for (const b of buf) n = n*256n + BigInt(b);
  let s = '';
  while (n > 0n){ s = AL[Number(n % 58n)] + s; n = n/58n; }
  let z = 0; while (z < buf.length && buf[z] === 0) z++;
  return '1'.repeat(z) + (s === '' ? (buf.length ? '' : '') : s);
}
function encFull(buf){
  // python base58 b58encode: leading zeros -> '1', then value; if value 0 and no bytes -> ''
  let n = 0n;
  for (const b of buf) n = n*256n + BigInt(b);
  let s='';
  while(n>0n){ s = AL[Number(n%58n)] + s; n=n/58n; }
  let z=0; while(z<buf.length && buf[z]===0) z++;
  return '1'.repeat(z)+s;
}
function dec(str){
  let z=0; while(z<str.length && str[z]==='1') z++;
  let n=0n;
  for(const ch of str){ const i=AL.indexOf(ch); if(i<0) throw new Error('bad char '+ch); n=n*58n+BigInt(i); }
  let bytes=[];
  while(n>0n){ bytes.unshift(Number(n%256n)); n=n/256n; }
  // python base58 b58decode pads to origlen-newlen... actually: leading '1' count
  return Buffer.concat([Buffer.alloc(z,0), Buffer.from(bytes)]);
}
function encInt(i){ if(i===0) return AL[0]; let n=BigInt(i); let s=''; while(n>0n){ s=AL[Number(n%58n)]+s; n=n/58n;} return s;}
module.exports={AL,encFull,dec,encInt};
if(require.main===module){
  const args=process.argv.slice(2);
  const mode=args[0];
  if(mode==='enc') console.log(encFull(Buffer.from(args[1],'utf8')));
  else if(mode==='dec') console.log(JSON.stringify(dec(args[1]).toString('latin1')));
  else if(mode==='decraw') console.log(dec(args[1]).toString('hex'));
  else if(mode==='encint') console.log(encInt(parseInt(args[1])));
}
